// Fixed and sticky elements become regular parts of the page.
const changed = [];
for (const el of document.querySelectorAll('body *')) {
  const { position } = getComputedStyle(el);
  if (position !== 'fixed' && position !== 'sticky') continue;
  changed.push([el, el.style.getPropertyValue('position'), el.style.getPropertyPriority('position')]);
  el.style.setProperty('position', position === 'fixed' ? 'absolute' : 'static', 'important');
}
potion.onStop(() => {
  for (const [el, value, priority] of changed) value ? el.style.setProperty('position', value, priority) : el.style.removeProperty('position');
});
